namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var (lines, accepted, total) = PrepareBatch(
            items, settlementCurrency, percentageFee, fixedFee, submissionLimit);

        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");

        if (string.IsNullOrWhiteSpace(merchantId))
            return CreateRejectedResult(lines, accepted, "invalid-merchant");

        return SubmitBatch(merchantId, settlementCurrency, gateway, lines, accepted, total);
    }

    private static (List<SettlementLine> Lines, List<(string Reference, decimal Net)> Accepted, decimal Total)
        PrepareBatch(IEnumerable<PaymentItem> items, string settlementCurrency, decimal percentageFee,
            decimal fixedFee, decimal submissionLimit)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<(string Reference, decimal Net)>();
        var seen = new HashSet<string>(StringComparer.Ordinal);
        var total = 0m;

        foreach (var item in items)
        {
            var rejectionReason = GetValidationFailure(item, settlementCurrency, seen);
            if (rejectionReason is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionReason));
                continue;
            }

            var net = CalculateNet(item.GrossAmount, percentageFee, fixedFee);
            rejectionReason = GetFinancialFailure(net, total, submissionLimit);
            if (rejectionReason is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, rejectionReason));
                continue;
            }

            accepted.Add((item.Reference, net));
            total += net;
        }

        return (lines, accepted, total);
    }

    private static string? GetValidationFailure(PaymentItem item, string settlementCurrency, HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static decimal CalculateNet(decimal grossAmount, decimal percentageFee, decimal fixedFee)
    {
        var fee = decimal.Round(grossAmount * percentageFee + fixedFee, 2);
        return decimal.Round(grossAmount - fee, 2);
    }

    private static string? GetFinancialFailure(decimal net, decimal currentTotal, decimal submissionLimit)
    {
        if (net <= 0m)
            return "fee-exceeds-amount";
        if (currentTotal + net > submissionLimit)
            return "batch-limit";

        return null;
    }

    private static SettlementResult SubmitBatch(string merchantId, string settlementCurrency,
        ISettlementGateway gateway, List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, decimal total)
    {
        var references = accepted.Select(entry => entry.Reference).ToArray();
        var gatewayResult = gateway.Submit(merchantId, settlementCurrency, total, references);
        if (!gatewayResult.Accepted)
            return CreateRejectedResult(lines, accepted, $"gateway-{gatewayResult.Code}");

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        var status = lines.Any(line => line.Status != "submitted") ? "partial" : "submitted";
        return new SettlementResult(lines, total, status);
    }

    private static SettlementResult CreateRejectedResult(List<SettlementLine> lines,
        List<(string Reference, decimal Net)> accepted, string reason)
    {
        var rejectedLines = accepted.Select(entry => new SettlementLine(entry.Reference, 0m, reason));
        return new SettlementResult([.. lines, .. rejectedLines], 0m, "rejected");
    }
}
